\begin{definition}
\label{def:2.1}
[Continuous functions]
Let $(X,d_X)$ and $(Y,d_Y)$ be metric spaces, and let $f\colon X\to Y$.
\begin{enumerate}
\item For $x_0\in X$, the function $f$ is \emph{continuous at $x_0$} if for every $\varepsilon>0$ there exists $\delta>0$ such that for all $x\in X$,
\[
\label{eq:2.u1}
d_X(x,x_0)<\delta\implies d_Y\bigl(f(x),f(x_0)\bigr)<\varepsilon.
\]
\item The function $f$ is \emph{continuous} (on $X$) if $f$ is continuous at every $x\in X$.
\end{enumerate}
\end{definition}

\begin{theorem}
\label{thm:2.1}
[Continuity preserves convergence]
Let $(X,d_X)$ and $(Y,d_Y)$ be metric spaces, let $f:X\to Y$ be a function, and let $x_0\in X$. The following statements are equivalent:
\begin{enumerate}
\item[(a)] $f$ is continuous at $x_0$, i.e., for every $\varepsilon>0$ there exists $\delta>0$ such that $d_X(x,x_0)<\delta$ implies $d_Y(f(x),f(x_0))<\varepsilon$.
\item[(b)] For every sequence $(x^{(n)})_{n=1}^\infty$ in $X$ with $x^{(n)}\to x_0$ in $(X,d_X)$, one has $f(x^{(n)})\to f(x_0)$ in $(Y,d_Y)$.
\item[(c)] For every open set $V\subseteq Y$ with $f(x_0)\in V$, there exists an open set $U\subseteq X$ with $x_0\in U$ such that $f(U)\subseteq V$.
\end{enumerate}
\end{theorem}

proof:
\begin{proof}
\label{prf:thm:2.1}
(a)$\Rightarrow$(b). Assume (a). Let $(x^{(n)})$ be a sequence in $X$ with $x^{(n)}\to x_0$. Let $\varepsilon>0$. By (a), there exists $\delta>0$ such that if $d_X(x,x_0)<\delta$ then $d_Y(f(x),f(x_0))<\varepsilon$. Since $x^{(n)}\to x_0$, there exists $N\in\mathbb{N}$ such that for all $n\ge N$ one has $d_X(x^{(n)},x_0)<\delta$. Hence for all $n\ge N$, $d_Y(f(x^{(n)}),f(x_0))<\varepsilon$. This shows $f(x^{(n)})\to f(x_0)$.

(b)$\Rightarrow$(a). Assume (b). Suppose, for contradiction, that (a) fails. Then there exists $\varepsilon_0>0$ such that for every $\delta>0$ there exists $x\in X$ with $d_X(x,x_0)<\delta$ and $d_Y(f(x),f(x_0))\ge \varepsilon_0$. For each $n\in\mathbb{N}$, apply this with $\delta=1/n$ to obtain $x^{(n)}\in X$ such that
\[
\label{eq:2.u2}
d_X(x^{(n)},x_0)<\frac{1}{n}\quad\text{and}\quad d_Y(f(x^{(n)}),f(x_0))\ge \varepsilon_0.
\]
Then $x^{(n)}\to x_0$ in $X$, but $f(x^{(n)})\not\to f(x_0)$ in $Y$ because the distance from $f(x^{(n)})$ to $f(x_0)$ is bounded below by $\varepsilon_0$ for all $n$, contradicting (b). Therefore (a) holds.

(a)$\Rightarrow$(c). Assume (a). Let $V\subseteq Y$ be open with $f(x_0)\in V$. Since $V$ is open, there exists $\varepsilon>0$ such that the open ball $B_Y(f(x_0),\varepsilon)=\{y\in Y: d_Y(y,f(x_0))<\varepsilon\}$ satisfies $B_Y(f(x_0),\varepsilon)\subseteq V$. By (a), there exists $\delta>0$ such that $d_X(x,x_0)<\delta$ implies $d_Y(f(x),f(x_0))<\varepsilon$, i.e., $f(B_X(x_0,\delta))\subseteq B_Y(f(x_0),\varepsilon)\subseteq V$. Setting $U=B_X(x_0,\delta)$ gives an open set $U\subseteq X$ with $x_0\in U$ and $f(U)\subseteq V$.

(c)$\Rightarrow$(a). Assume (c). Let $\varepsilon>0$ and define the open set $V=B_Y(f(x_0),\varepsilon)\subseteq Y$, which contains $f(x_0)$. By (c), there exists an open set $U\subseteq X$ with $x_0\in U$ and $f(U)\subseteq V$. Since $U$ is open and contains $x_0$, there exists $\delta>0$ such that $B_X(x_0,\delta)\subseteq U$. Then for any $x\in X$ with $d_X(x,x_0)<\delta$, one has $x\in B_X(x_0,\delta)\subseteq U$, hence $f(x)\in f(U)\subseteq V=B_Y(f(x_0),\varepsilon)$, which means $d_Y(f(x),f(x_0))<\varepsilon$. This is exactly continuity of $f$ at $x_0$.

Therefore (a), (b), and (c) are equivalent.
\end{proof}

\begin{proof}
\label{prf:thm:2.2}
(a)$\Rightarrow$(b). Assume $f$ is continuous. Let $x^{(n)}\to x_0$ in $X$ and let $\varepsilon>0$. By continuity of $f$ at $x_0$, there exists $\delta>0$ such that $d_X(x,x_0)<\delta$ implies $d_Y(f(x),f(x_0))<\varepsilon$. Since $x^{(n)}\to x_0$, there exists $N$ such that $d_X(x^{(n)},x_0)<\delta$ for all $n\ge N$. Hence $d_Y(f(x^{(n)}),f(x_0))<\varepsilon$ for all $n\ge N$, so $f(x^{(n)})\to f(x_0)$.

(b)$\Rightarrow$(a). Assume (b). Fix $x_0\in X$. If $f$ is not continuous at $x_0$, then there exists $\varepsilon_0>0$ such that for every $\delta>0$ there exists $x\in X$ with $d_X(x,x_0)<\delta$ and $d_Y(f(x),f(x_0))\ge \varepsilon_0$. For each $n\in\mathbb{N}$, choose $x^{(n)}\in X$ such that $d_X(x^{(n)},x_0)<1/n$ and $d_Y(f(x^{(n)}),f(x_0))\ge \varepsilon_0$. Then $x^{(n)}\to x_0$, but $f(x^{(n)})$ does not converge to $f(x_0)$, contradicting (b). Therefore $f$ is continuous at $x_0$, and since $x_0$ was arbitrary, $f$ is continuous on $X$.

(a)$\Rightarrow$(c). Assume $f$ is continuous and let $V\subseteq Y$ be open. Let $x_0\in f^{-1}(V)$, so $f(x_0)\in V$. Since $V$ is open, there exists $\varepsilon>0$ such that $B_Y(f(x_0),\varepsilon):=\{y\in Y: d_Y(y,f(x_0))<\varepsilon\}\subseteq V$. By continuity of $f$ at $x_0$, there exists $\delta>0$ such that $d_X(x,x_0)<\delta$ implies $d_Y(f(x),f(x_0))<\varepsilon$, hence $f(x)\in B_Y(f(x_0),\varepsilon)\subseteq V$. Therefore $B_X(x_0,\delta)\subseteq f^{-1}(V)$, showing that $f^{-1}(V)$ is open.

(c)$\Rightarrow$(a). Assume (c). Fix $x_0\in X$ and $\varepsilon>0$. The set $V:=B_Y(f(x_0),\varepsilon)$ is open in $Y$, hence $U:=f^{-1}(V)$ is open in $X$ by (c). Since $x_0\in U$ and $U$ is open, there exists $\delta>0$ such that $B_X(x_0,\delta)\subseteq U$. If $d_X(x,x_0)<\delta$, then $x\in U$, so $f(x)\in V$, i.e., $d_Y(f(x),f(x_0))<\varepsilon$. This proves continuity of $f$ at $x_0$, and thus on $X$.

(c)$\Rightarrow$(d). Assume (c) and let $F\subseteq Y$ be closed. Then $Y\setminus F$ is open, so $f^{-1}(Y\setminus F)$ is open in $X$. Since $f^{-1}(Y\setminus F)=X\setminus f^{-1}(F)$, the complement of $f^{-1}(F)$ is open, hence $f^{-1}(F)$ is closed.

(d)$\Rightarrow$(c). Assume (d) and let $V\subseteq Y$ be open. Then $Y\setminus V$ is closed, so $f^{-1}(Y\setminus V)$ is closed in $X$. Since $f^{-1}(Y\setminus V)=X\setminus f^{-1}(V)$, the complement of $f^{-1}(V)$ is closed, hence $f^{-1}(V)$ is open.

The implications above show that (a), (b), (c), and (d) are equivalent.
\end{proof}

