\begin{theorem}
\label{thm:2.3}
(Continuity preserved by composition) Let $(X,d_X)$, $(Y,d_Y)$, and $(Z,d_Z)$ be metric spaces.
\begin{enumerate}
\item[(a)] Let $f\colon X\to Y$ and $g\colon Y\to Z$. If $f$ is continuous at $x_0\in X$ and $g$ is continuous at $f(x_0)\in Y$, then the composition $g\circ f\colon X\to Z$, defined by $(g\circ f)(x)=g(f(x))$, is continuous at $x_0$.
\item[(b)] Let $f\colon X\to Y$ and $g\colon Y\to Z$. If $f$ is continuous on $X$ and $g$ is continuous on $Y$, then $g\circ f$ is continuous on $X$.
\end{enumerate}
\end{theorem}

proof:
\begin{proof}
\label{prf:thm:2.3}
(a) Let $\varepsilon>0$. Since $g$ is continuous at $f(x_0)$, there exists $\eta>0$ such that for all $y\in Y$,
\[
\label{eq:2.u3}
d_Y(y,f(x_0))<\eta \implies d_Z(g(y),g(f(x_0)))<\varepsilon.
\]
Since $f$ is continuous at $x_0$, there exists $\delta>0$ such that for all $x\in X$,
\[
\label{eq:2.u4}
d_X(x,x_0)<\delta \implies d_Y(f(x),f(x_0))<\eta.
\]
Therefore, for all $x\in X$, if $d_X(x,x_0)<\delta$, then $d_Y(f(x),f(x_0))<\eta$, hence
\[
\label{eq:2.u5}
d_Z\bigl((g\circ f)(x),(g\circ f)(x_0)\bigr)=d_Z\bigl(g(f(x)),g(f(x_0))\bigr)<\varepsilon.
\]
Thus $g\circ f$ is continuous at $x_0$.

(b) Fix $x_0\in X$. Since $f$ is continuous at $x_0$ and $g$ is continuous at $f(x_0)$, part (a) implies that $g\circ f$ is continuous at $x_0$. Since $x_0$ was arbitrary, $g\circ f$ is continuous on $X$.
\end{proof}

