\begin{proposition}
\label{prop:2.1}
Let $X$ be a topological space and let $f\colon X\to\mathbb{R}$ be continuous. Define $f^2\colon X\to\mathbb{R}$ by $f^2(x):=f(x)^2$. Then $f^2$ is continuous.
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:2.1}
Let $g\colon\mathbb{R}\to\mathbb{R}$ be defined by $g(t):=t^2$. Then $g$ is continuous and $f^2=g\circ f$. Since the composition of continuous functions is continuous, $f^2$ is continuous.
\end{proof}

