\begin{proposition}
\label{prop:2.4}
Let \( f : X \to Y \) be a function from one metric space \( (X, d_X) \) to another \( (Y, d_Y) \). Suppose that the image \( f(X) \) of \( X \) is contained in some subset \( E \subseteq Y \) of \( Y \). Let \( g : X \to E \) be the function which is the same as \( f \) but with the codomain restricted from \( Y \) to \( E \), thus \( g(x) = f(x) \) for all \( x \in X \). We give \( E \) the metric \( d_Y|_{E \times E} \) induced from \( Y \). For any \( x_0 \in X \), that \( f \) is continuous at \( x_0 \) if and only if \( g \) is continuous at \( x_0 \).
\end{proposition}

\begin{definition}
\label{def:2.2}
[Pairing of functions]
Let $f\colon X\to Y$ and $g\colon X\to Z$ be functions. The \emph{pairing} of $f$ and $g$ is the function $(f,g)\colon X\to Y\times Z$ defined by
\[
\label{eq:2.u8}
(f,g)(x):=(f(x),g(x))\qquad (x\in X).
\]
\end{definition}

\begin{lemma}
\label{lem:2.1}
Let \( f : X \to \mathbb{R} \) and \( g : X \to \mathbb{R} \) be functions, and let \( (f, g) : X \to \mathbb{R}^2 \) be their direct sum. We give \( \mathbb{R}^2 \) the Euclidean metric.

(a) If \( x_0 \in X \), then \( f \) and \( g \) are both continuous at \( x_0 \) if and only if \( (f, g) \) is continuous at \( x_0 \).

(b) \( f \) and \( g \) are both continuous if and only if \( (f, g) \) is continuous.
\end{lemma}

\begin{lemma}
\label{lem:2.2}
The functions $+:\mathbb{R}^2\to\mathbb{R}$, $-:\mathbb{R}^2\to\mathbb{R}$, $\cdot:\mathbb{R}^2\to\mathbb{R}$, $\max:\mathbb{R}^2\to\mathbb{R}$, and $\min:\mathbb{R}^2\to\mathbb{R}$ defined by
\[
\label{eq:2.u13}
+(x,y)=x+y,\qquad -(x,y)=x-y,\qquad \cdot(x,y)=xy,\qquad \max(x,y)=\max\{x,y\},\qquad \min(x,y)=\min\{x,y\}
\]
are continuous. The function $/:\mathbb{R}\times(\mathbb{R}\setminus\{0\})\to\mathbb{R}$ defined by
\[
\label{eq:2.u14}
/(x,y)=x/y
\]
is continuous on its domain. For each $c\in\mathbb{R}$, the function $m_c:\mathbb{R}\to\mathbb{R}$ defined by $m_c(x)=cx$ is continuous.
\end{lemma}

\begin{theorem}
\label{thm:2.4}
Let $(X, d)$ be a metric space, and let $f : X \to \mathbb{R}$ and $g : X \to \mathbb{R}$ be functions. Let $c$ be a real number.

(a) If $x_0 \in X$ and $f$ and $g$ are continuous at $x_0$, then the functions $f + g : X \to \mathbb{R}$, $f - g : X \to \mathbb{R}$, $fg : X \to \mathbb{R}$, $\max(f, g) : X \to \mathbb{R}$, $\min(f, g) : X \to \mathbb{R}$, and $cf : X \to \mathbb{R}$ (see Definition 9.2.1 for definitions) are also continuous at $x_0$. If $g(x) \neq 0$ for all $x \in X$, then $f/g : X \to \mathbb{R}$ is also continuous.

(b) If $f$ and $g$ are continuous, then the functions $f + g : X \to \mathbb{R}$, $f - g : X \to \mathbb{R}$, $fg : X \to \mathbb{R}$, $\max(f, g) : X \to \mathbb{R}$, $\min(f, g) : X \to \mathbb{R}$, and $cf : X \to \mathbb{R}$ are also continuous at $x_0$. If $g(x) \neq 0$ for all $x \in X$, then $f/g : X \to \mathbb{R}$ is also continuous at $x_0$.
\end{theorem}

proof:
\begin{proof}
\label{prf:thm:2.4}
(a) Since $f$ and $g$ are continuous at $x_0$, the map $F:X\to\mathbb{R}^2$ defined by $F(x)=(f(x),g(x))$ is continuous at $x_0$. Define continuous functions $\phi_1,\phi_2,\phi_3,\phi_4,\phi_5:\mathbb{R}^2\to\mathbb{R}$ and $\psi:\mathbb{R}\to\mathbb{R}$ by
\[
\label{eq:2.u26}
\phi_1(u,v)=u+v,\quad \phi_2(u,v)=u-v,\quad \phi_3(u,v)=uv,\quad \phi_4(u,v)=\max\{u,v\},\quad \phi_5(u,v)=\min\{u,v\},
\]
\[
\label{eq:2.u27}
\psi(u)=cu.
\]
Then
\[
\label{eq:2.u28}
f+g=\phi_1\circ F,\quad f-g=\phi_2\circ F,\quad fg=\phi_3\circ F,\quad \max(f,g)=\phi_4\circ F,\quad \min(f,g)=\phi_5\circ F,\quad cf=\psi\circ f.
\]
Each right-hand side is a composition of functions continuous at the relevant point, hence each left-hand side is continuous at $x_0$.

If $g(x)\neq 0$ for all $x\in X$, the reciprocal map $r:\mathbb{R}\setminus\{0\}\to\mathbb{R}$, $r(t)=1/t$, is continuous, and $r\circ g$ is continuous at $x_0$. Since $f/g=f\cdot (r\circ g)$ and the product of two functions continuous at $x_0$ is continuous at $x_0$, the quotient $f/g$ is continuous at $x_0$.

(b) For each $x_0\in X$, the hypotheses imply that $f$ and $g$ are continuous at $x_0$. Applying part (a) at each $x_0$ gives continuity at every point of $X$ for the listed combinations, hence continuity on $X$.
\end{proof}

