\begin{proposition}
\label{prop:2.6}
Let $(X,d)$ be a metric space and let $f:X\to\mathbb{R}$ be continuous. Define $|f|:X\to\mathbb{R}$ by $|f|(x)=|f(x)|$ for all $x\in X$. Then $|f|$ is continuous on $X$.
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:2.6}
Fix $x_0\in X$. Since $f$ is continuous at $x_0$, for every $\varepsilon>0$ there exists $\delta>0$ such that $d(x,x_0)<\delta$ implies $|f(x)-f(x_0)|<\varepsilon$. For all $a,b\in\mathbb{R}$, the reverse triangle inequality gives $\bigl||a|-|b|\bigr|\le |a-b|$. Applying this with $a=f(x)$ and $b=f(x_0)$ yields
\[
\label{eq:2.u29}
\bigl||f(x)|-|f(x_0)|\bigr|\le |f(x)-f(x_0)|.
\]
Hence, if $d(x,x_0)<\delta$, then
\[
\label{eq:2.u30}
\bigl||f|(x)-|f|(x_0)\bigr|=\bigl||f(x)|-|f(x_0)|\bigr|<\varepsilon.
\]
Therefore $|f|$ is continuous at $x_0$. Since $x_0$ was arbitrary, $|f|$ is continuous on $X$.
\end{proof}

