\begin{proposition}
\label{prop:2.7}
Let $\pi_1,\pi_2:\mathbb{R}^2\to\mathbb{R}$ be defined by $\pi_1(x,y)=x$ and $\pi_2(x,y)=y$. Then $\pi_1$ and $\pi_2$ are continuous (with respect to the Euclidean metrics on $\mathbb{R}^2$ and $\mathbb{R}$).

Moreover, let $(X,d)$ be a metric space and let $f:\mathbb{R}\to X$ be continuous. Define $g_1,g_2:\mathbb{R}^2\to X$ by $g_1(x,y)=f(x)$ and $g_2(x,y)=f(y)$. Then $g_1$ and $g_2$ are continuous (with respect to the Euclidean metric on $\mathbb{R}^2$ and the metric $d$ on $X$).
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:2.7}
For $\pi_1$, let $(x_0,y_0)\in\mathbb{R}^2$ and let $\varepsilon>0$. If $\sqrt{(x-x_0)^2+(y-y_0)^2}<\varepsilon$, then $|x-x_0|\le \sqrt{(x-x_0)^2+(y-y_0)^2}<\varepsilon$, hence
\[
\label{eq:2.u31}
|\pi_1(x,y)-\pi_1(x_0,y_0)|=|x-x_0|<\varepsilon.
\]
Thus $\pi_1$ is continuous at $(x_0,y_0)$, and therefore continuous on $\mathbb{R}^2$. The same argument with $y$ in place of $x$ shows that $\pi_2$ is continuous.

For $g_1$, fix $(x_0,y_0)\in\mathbb{R}^2$ and $\varepsilon>0$. Since $f$ is continuous at $x_0$, there exists $\delta>0$ such that $|x-x_0|<\delta$ implies $d(f(x),f(x_0))<\varepsilon$. If $\sqrt{(x-x_0)^2+(y-y_0)^2}<\delta$, then $|x-x_0|<\delta$, hence
\[
\label{eq:2.u32}
d\bigl(g_1(x,y),g_1(x_0,y_0)\bigr)=d\bigl(f(x),f(x_0)\bigr)<\varepsilon.
\]
Therefore $g_1$ is continuous at $(x_0,y_0)$ and hence continuous on $\mathbb{R}^2$. The proof for $g_2$ is identical, using continuity of $f$ at $y_0$ and the estimate $|y-y_0|\le \sqrt{(x-x_0)^2+(y-y_0)^2}$.
\end{proof}

