\begin{proposition}
\label{prop:2.8}
Let $n,m\ge 0$ be integers, and let $c_{ij}\in\mathbb{R}$ for $0\le i\le n$, $0\le j\le m$. Define $P:\mathbb{R}^2\to\mathbb{R}$ by
\[
\label{eq:2.u34}
P(x,y):=\sum_{i=0}^{n}\sum_{j=0}^{m} c_{ij} x^i y^j.
\]
Then $P$ is continuous on $\mathbb{R}^2$. Moreover, if $(X,d)$ is a metric space and $f,g:X\to\mathbb{R}$ are continuous, then the map $P(f,g):X\to\mathbb{R}$ defined by
\[
\label{eq:2.u35}
P(f,g)(x):=P(f(x),g(x))
\]
is continuous.
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:2.8}
For each pair $(i,j)$ with $0\le i\le n$ and $0\le j\le m$, define $h_{ij}:\mathbb{R}^2\to\mathbb{R}$ by $h_{ij}(x,y)=x^i y^j$. The coordinate projections $(x,y)\mapsto x$ and $(x,y)\mapsto y$ are continuous, and the map $t\mapsto t^k$ is continuous on $\mathbb{R}$ for each integer $k\ge 0$. Hence $(x,y)\mapsto x^i$ and $(x,y)\mapsto y^j$ are continuous, and therefore $h_{ij}$ is continuous as a product of continuous functions. Since scalar multiples and finite sums of continuous functions are continuous, the finite sum
\[
\label{eq:2.u36}
P=\sum_{i=0}^{n}\sum_{j=0}^{m} c_{ij} h_{ij}
\]
is continuous on $\mathbb{R}^2$.

Now let $(X,d)$ be a metric space and let $f,g:X\to\mathbb{R}$ be continuous. Define $H:X\to\mathbb{R}^2$ by $H(x)=(f(x),g(x))$. For any $x_0\in X$ and $\varepsilon>0$, continuity of $f$ and $g$ at $x_0$ yields $\delta_1,\delta_2>0$ such that $d(x,x_0)<\delta_1$ implies $|f(x)-f(x_0)|<\varepsilon$, and $d(x,x_0)<\delta_2$ implies $|g(x)-g(x_0)|<\varepsilon$. With $\delta=\min\{\delta_1,\delta_2\}$, if $d(x,x_0)<\delta$ then
\[
\label{eq:2.u37}
\|(f(x),g(x))-(f(x_0),g(x_0))\|_\infty=\max\{|f(x)-f(x_0)|,|g(x)-g(x_0)|\}<\varepsilon,
\]
so $H$ is continuous. Since $P$ is continuous on $\mathbb{R}^2$, the composition $P\circ H$ is continuous on $X$. As $(P\circ H)(x)=P(f(x),g(x))=P(f,g)(x)$, the map $P(f,g)$ is continuous.
\end{proof}

