\begin{proposition}
\label{prop:2.10}
Let $k\ge 1$, let $I\subseteq\mathbb{N}^k$ be finite, let $c:I\to\mathbb{R}$, and define $P:\mathbb{R}^k\to\mathbb{R}$ by
\[
\label{eq:2.u41}
P(x_1,\ldots,x_k):=\sum_{(i_1,\ldots,i_k)\in I} c(i_1,\ldots,i_k)\, x_1^{i_1}\cdots x_k^{i_k}.
\]
Then $P$ is continuous on $\mathbb{R}^k$ (with the usual Euclidean topology).
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:2.10}
Fix $\alpha=(i_1,\ldots,i_k)\in I$ and write $c_\alpha:=c(i_1,\ldots,i_k)$. The coordinate projection $\pi_j:\mathbb{R}^k\to\mathbb{R}$ given by $\pi_j(x_1,\ldots,x_k)=x_j$ is continuous for each $j$. For each $n\in\mathbb{N}$, the map $p_n:\mathbb{R}\to\mathbb{R}$ defined by $p_n(t)=t^n$ is continuous (for example, by induction using that multiplication on $\mathbb{R}$ is continuous). Hence $x\mapsto (\pi_j(x))^{i_j}=x_j^{i_j}$ is continuous on $\mathbb{R}^k$ for each $j$, and therefore the product
\[
\label{eq:2.u42}
M_\alpha(x):=x_1^{i_1}\cdots x_k^{i_k}
\]
is continuous as a finite product of continuous functions. Multiplication by the scalar $c_\alpha$ is continuous, so $x\mapsto c_\alpha M_\alpha(x)$ is continuous.

Since $I$ is finite, $P$ is a finite sum of the continuous functions $x\mapsto c_\alpha M_\alpha(x)$, and a finite sum of continuous functions is continuous. Thus $P$ is continuous on $\mathbb{R}^k$.
\end{proof}

