\begin{proposition}
\label{prop:2.11}
Let $(X,d_X)$ and $(Y,d_Y)$ be metric spaces. Define a function $d_{X\times Y}:(X\times Y)\times (X\times Y)\to [0, \infty)$ by
\[
\label{eq:2.u44}
d_{X\times Y}\bigl((x,y),(x',y')\bigr):=d_X(x,x')+d_Y(y,y')
\]
for all $(x,y),(x',y')\in X\times Y$. Then $d_{X\times Y}$ is a metric on $X\times Y$, and hence $(X\times Y,d_{X\times Y})$ is a metric space.
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:2.11}
Let $(x,y),(x',y'),(x'',y'')\in X\times Y$.

Nonnegativity holds since $d_X$ and $d_Y$ are nonnegative, so $d_{X\times Y}((x,y),(x',y'))\ge 0$.

If $d_{X\times Y}((x,y),(x',y'))=0$, then $d_X(x,x')+d_Y(y,y')=0$. As each term is nonnegative, $d_X(x,x')=0$ and $d_Y(y,y')=0$, hence $x=x'$ and $y=y'$; thus $(x,y)=(x',y')$. Conversely, if $(x,y)=(x',y')$, then $d_{X\times Y}((x,y),(x',y'))=d_X(x,x)+d_Y(y,y)=0$.

Symmetry follows from symmetry of $d_X$ and $d_Y$:
\[
\label{eq:2.u45}
d_{X\times Y}((x,y),(x',y'))=d_X(x,x')+d_Y(y,y')=d_X(x',x)+d_Y(y',y)=d_{X\times Y}((x',y'),(x,y)).
\]

For the triangle inequality, apply the triangle inequality in $X$ and in $Y$:
\[
\label{eq:2.u46}
\begin{aligned}
d_{X\times Y}((x,y),(x'',y''))
&= d_X(x,x'')+d_Y(y,y'')\\
&\le \bigl(d_X(x,x')+d_X(x',x'')\bigr)+\bigl(d_Y(y,y')+d_Y(y',y'')\bigr)\\
&= d_{X\times Y}((x,y),(x',y'))+d_{X\times Y}((x',y'),(x'',y'')).
\end{aligned}
\]

Therefore $d_{X\times Y}$ is a metric on $X\times Y$.
\end{proof}

