\begin{proposition}
\label{prop:2.14}
Define $f:\mathbb{R}^2\to\mathbb{R}$ by
\[
\label{eq:2.u57}
f(x,y)=\begin{cases}
\dfrac{xy}{x^2+y^2}, & (x,y)\neq(0,0),\\
0, & (x,y)=(0,0).
\end{cases}
\]
Then the following statements hold.
\begin{enumerate}
\item For each fixed $x\in\mathbb{R}$, the function $g_x:\mathbb{R}\to\mathbb{R}$ defined by $g_x(y)=f(x,y)$ is continuous on $\mathbb{R}$.
\item For each fixed $y\in\mathbb{R}$, the function $h_y:\mathbb{R}\to\mathbb{R}$ defined by $h_y(x)=f(x,y)$ is continuous on $\mathbb{R}$.
\end{enumerate}
\end{proposition}

\begin{theorem}
\label{thm:2.5}
[Continuous maps preserve compactness]
Let \(f: X \to Y\) be a continuous map from one metric space \((X, d_X)\) to another \((Y, d_Y)\). Let \(K \subseteq X\) be any compact subset of \(X\). Then the image \(f(K) := \{f(x) : x \in K\}\) of \(K\) is also compact.
\end{theorem}

proof:
\begin{proof}
\label{prf:thm:2.5}
Let $(y_n)$ be a sequence in $f(K)$. For each $n$ choose $x_n\in K$ such that $y_n=f(x_n)$. Since $K$ is compact, it is sequentially compact, so there exist a subsequence $(x_{n_k})$ and a point $x\in K$ such that $x_{n_k}\to x$ in $X$. By continuity of $f$, $f(x_{n_k})\to f(x)$ in $Y$. Since $f(x_{n_k})=y_{n_k}$ and $f(x)\in f(K)$, the subsequence $(y_{n_k})$ converges to a point of $f(K)$. Thus every sequence in $f(K)$ has a convergent subsequence with limit in $f(K)$, so $f(K)$ is sequentially compact. In metric spaces, sequential compactness is equivalent to compactness; hence $f(K)$ is compact.
\end{proof}

