\begin{definition}
\label{def:2.6}
[Uniform continuity]
Let $(X,d_X)$ and $(Y,d_Y)$ be metric spaces, and let $f:X\to Y$ be a function. The function $f$ is \emph{uniformly continuous} on $X$ if for every $\varepsilon>0$ there exists $\delta>0$ such that for all $x,x'\in X$, the implication
\[
\label{eq:2.u62}
d_X(x,x')<\delta \;\Longrightarrow\; d_Y\bigl(f(x),f(x')\bigr)<\varepsilon
\]
holds.
\end{definition}

\begin{theorem}
\label{thm:2.7}
Let $(X,d_X)$ and $(Y,d_Y)$ be metric spaces, and assume that $X$ is compact. For a function $f\colon X\to Y$, $f$ is continuous on $X$ if and only if $f$ is uniformly continuous on $X$.
\end{theorem}

\begin{proposition}
\label{prop:2.16}
Let $(X,d_X)$, $(Y,d_Y)$, and $(Z,d_Z)$ be metric spaces. If $f\colon X\to Y$ and $g\colon Y\to Z$ are uniformly continuous, then $g\circ f\colon X\to Z$ is uniformly continuous.
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:2.16}
Let $\varepsilon>0$. Since $g$ is uniformly continuous, there exists $\eta>0$ such that for all $y_1,y_2\in Y$, if $d_Y(y_1,y_2)<\eta$ then $d_Z(g(y_1),g(y_2))<\varepsilon$.

Since $f$ is uniformly continuous, there exists $\delta>0$ such that for all $x_1,x_2\in X$, if $d_X(x_1,x_2)<\delta$ then $d_Y(f(x_1),f(x_2))<\eta$.

Now for any $x_1,x_2\in X$ with $d_X(x_1,x_2)<\delta$, one has $d_Y(f(x_1),f(x_2))<\eta$, hence
\[
\label{eq:2.u68}
d_Z\bigl((g\circ f)(x_1),(g\circ f)(x_2)\bigr)=d_Z\bigl(g(f(x_1)),g(f(x_2))\bigr)<\varepsilon.
\]
Therefore $g\circ f$ is uniformly continuous.
\end{proof}

