\begin{proposition}
\label{prop:2.17}
Let $(X,d_X)$ be a metric space, and let $f,g\colon X\to\mathbb{R}$ be uniformly continuous. Equip $\mathbb{R}^2$ with the standard metric
\[
\label{eq:2.u69}
d_{\mathbb{R}^2}((a,b),(c,d)):=\sqrt{(a-c)^2+(b-d)^2}.
\]
Define $(f,g)\colon X\to\mathbb{R}^2$ by $(f,g)(x):=(f(x),g(x))$. Then $(f,g)$ is uniformly continuous.
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:2.17}
Let $\varepsilon>0$. Since $f$ is uniformly continuous, there exists $\delta_1>0$ such that for all $x,y\in X$, if $d_X(x,y)<\delta_1$ then $|f(x)-f(y)|<\varepsilon/\sqrt{2}$. Since $g$ is uniformly continuous, there exists $\delta_2>0$ such that for all $x,y\in X$, if $d_X(x,y)<\delta_2$ then $|g(x)-g(y)|<\varepsilon/\sqrt{2}$.

Let $\delta:=\min\{\delta_1,\delta_2\}$. If $d_X(x,y)<\delta$, then both inequalities hold, and hence
\[
\label{eq:2.u70}
d_{\mathbb{R}^2}\bigl((f(x),g(x)),(f(y),g(y))\bigr)
=\sqrt{|f(x)-f(y)|^2+|g(x)-g(y)|^2}
<\sqrt{\frac{\varepsilon^2}{2}+\frac{\varepsilon^2}{2}}=\varepsilon.
\]
Therefore, for all $x,y\in X$, $d_X(x,y)<\delta$ implies $d_{\mathbb{R}^2}((f,g)(x),(f,g)(y))<\varepsilon$, so $(f,g)$ is uniformly continuous.
\end{proof}

