\begin{proposition}
\label{prop:2.18}
Let $\mathbb{R}^2$ be equipped with the Euclidean metric $d((x,y),(x',y'))=\sqrt{(x-x')^2+(y-y')^2}$ and let $\mathbb{R}$ have the usual metric. Define maps $a,s,m\colon\mathbb{R}^2\to\mathbb{R}$ by
\[
\label{eq:2.u71}
a(x,y)=x+y,\qquad s(x,y)=x-y,\qquad m(x,y)=xy.
\]
Then $a$ and $s$ are uniformly continuous on $\mathbb{R}^2$, whereas $m$ is not uniformly continuous on $\mathbb{R}^2$.
\end{proposition}

\begin{proposition}
\label{prop:2.19}
Let $(X,d)$ be a metric space and let $f,g\colon X\to\mathbb{R}$ be uniformly continuous. Then the functions $f+g$ and $f-g$, defined by $(f\pm g)(x)=f(x)\pm g(x)$ for $x\in X$, are uniformly continuous on $X$.
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:2.19}
Fix $\varepsilon>0$. Since $f$ is uniformly continuous, there exists $\delta_f>0$ such that for all $x,y\in X$, if $d(x,y)<\delta_f$ then $|f(x)-f(y)|<\varepsilon/2$. Since $g$ is uniformly continuous, there exists $\delta_g>0$ such that for all $x,y\in X$, if $d(x,y)<\delta_g$ then $|g(x)-g(y)|<\varepsilon/2$.

Let $\delta=\min\{\delta_f,\delta_g\}$. For any $x,y\in X$ with $d(x,y)<\delta$, both inequalities hold, and therefore
\[
\label{eq:2.u77}
|(f+g)(x)-(f+g)(y)|\le |f(x)-f(y)|+|g(x)-g(y)|<\varepsilon/2+\varepsilon/2=\varepsilon.
\]
Hence $f+g$ is uniformly continuous.

Similarly,
\[
\label{eq:2.u78}
|(f-g)(x)-(f-g)(y)|=|(f(x)-f(y))-(g(x)-g(y))|\le |f(x)-f(y)|+|g(x)-g(y)|<\varepsilon,
\]
so $f-g$ is uniformly continuous.
\end{proof}

