\begin{definition}
\label{def:2.7}
[Connected and disconnected metric spaces]
 Let $(X, d)$ be a metric space. We say that $X$ is disconnected iff there exist disjoint non-empty open sets $V$ and $W$ in $X$ such that $V \cup W = X$. (Equivalently, $X$ is disconnected if and only if $X$ contains a non-empty proper subset which is simultaneously closed and open.) We say that $X$ is connected iff it is non-empty and not disconnected.

We declare the empty set $\varnothing$ as being special---it is neither connected nor disconnected; one could think of the empty set as ``unconnected''.

\end{definition}

\begin{definition}
\label{def:2.8}
[Connected sets]
Let $(X,d)$ be a metric space and let $Y\subseteq X$. Equip $Y$ with the subspace metric $d_Y:=d|_{Y\times Y}$. The subset $Y$ is called \emph{connected} if the metric space $(Y,d_Y)$ is connected. The subset $Y$ is called \emph{disconnected} if the metric space $(Y,d_Y)$ is disconnected.
\end{definition}

\begin{theorem}
\label{thm:2.8}
Let \( X \) be a non-empty subset of the real line \( \mathbb{R} \). Then the following statements are equivalent.

(a) \( X \) is connected.
(b) Whenever \( x, y \in X \) and \( x < y \), the interval \([x, y]\) is also contained in \( X \).
(c) \( X \) is an interval 
\end{enumerate}
\end{theorem}

\begin{theorem}
\label{thm:2.9}
[Continuity preserves connectedness]
Let \( f : X \to Y \) be a continuous map from one metric space \((X, d_X)\) to another \((Y, d_Y)\). Let \( E \) be any connected subset of \( X \). Then \( f(E) \) is also connected.
\end{theorem}

\begin{theorem}
\label{thm:2.10}
[Intermediate value theorem]
Let $(X,d_X)$ be a metric space, let $f:X\to\mathbb{R}$ be continuous, and let $E\subseteq X$ be connected. For any $a,b\in E$ and any $y\in\mathbb{R}$ satisfying either $f(a)\le y\le f(b)$ or $f(a)\ge y\ge f(b)$, there exists $c\in E$ such that $f(c)=y$.
\end{theorem}

proof:
\begin{proof}
\label{prf:thm:2.10}
Assume $f(a)\le y\le f(b)$; the other case follows by interchanging $a$ and $b$.

Define
\[
\label{eq:2.u84}
A:=E\cap f^{-1}(( -\infty,y))=\{x\in E: f(x)<y\},\qquad B:=E\cap f^{-1}((y,\infty))=\{x\in E: f(x)>y\}.
\]
Since $f$ is continuous, the sets $f^{-1}(( -\infty,y))$ and $f^{-1}((y,\infty))$ are open in $X$, hence $A$ and $B$ are open in the subspace topology on $E$. If there exists $c\in E$ with $f(c)=y$, the conclusion holds, so assume for contradiction that no such $c$ exists. Then $E\subseteq A\cup B$, and because $f(a)<y$ would imply $a\in A$ while $f(a)=y$ would contradict the assumption, it follows that $a\in A$. Similarly, $b\in B$ (since $f(b)\ge y$ and $f(b)=y$ is excluded).

Moreover, $A\cap B=\varnothing$ and $A,B\ne\varnothing$, so $E=A\cup B$ is a separation of $E$ into two disjoint nonempty open subsets of $E$, contradicting connectedness of $E$. Therefore there exists $c\in E$ with $f(c)=y$.
\end{proof}

