\begin{theorem}
\label{thm:2.11}
Let $X$ be a set with the discrete metric $d_{\mathrm{disc}}$. If $E\subseteq X$ contains at least two distinct points, then $E$ is disconnected (in the subspace topology induced by $d_{\mathrm{disc}}$).
\end{theorem}

proof:
\begin{proof}
\label{prf:thm:2.11}
Choose distinct points $a,b\in E$. Define
\[
\label{eq:2.u85}
A=\{a\},\qquad B=E\setminus\{a\}.
\]
Then $A$ and $B$ are nonempty, disjoint, and $E=A\cup B$. In the discrete metric, the open ball $B_{1/2}(a)=\{x\in X: d_{\mathrm{disc}}(x,a)<1/2\}$ equals $\{a\}$, so $\{a\}$ is open in $X$. Hence $A=E\cap\{a\}$ is open in the subspace $E$. Similarly, for any $x\in B$ one has $\{x\}$ open in $X$, so $B=\bigcup_{x\in B}(E\cap\{x\})$ is open in $E$.

Thus $E$ is the union of two disjoint nonempty open subsets $A$ and $B$, so $E$ is disconnected.
\end{proof}

content:
\begin{theorem}
\label{thm:2.12}
Let $(X,d)$ be a connected metric space and let $(Y,d_{\mathrm{disc}})$ be a metric space equipped with the discrete metric, i.e.
\[
\label{eq:2.u86}
d_{\mathrm{disc}}(y_1,y_2)=\begin{cases}0,&y_1=y_2,\\1,&y_1\neq y_2.\end{cases}
\]
For a function $f\colon X\to Y$, the following are equivalent:
\begin{enumerate}
\item $f$ is continuous;
\item $f$ is constant.
\end{enumerate}
\end{theorem}

proof:
\begin{proof}
\label{prf:thm:2.12}
$(2)\Rightarrow(1)$: If $f$ is constant, then $f$ is continuous.

$(1)\Rightarrow(2)$: Assume that $f$ is continuous. For each $y\in Y$, the singleton $\{y\}$ is open in $(Y,d_{\mathrm{disc}})$, since $B(y,1/2)=\{y\}$. Hence for each $y\in Y$ the set
\[
\label{eq:2.u87}
U_y:=f^{-1}(\{y\})
\]
is open in $X$ by continuity of $f$. If $f$ is not constant, there exist distinct $y_1,y_2\in Y$ with $U_{y_1}\neq\varnothing$ and $U_{y_2}\neq\varnothing$. Then $U_{y_1}$ and $X\setminus U_{y_1}=\bigcup_{y\in Y\setminus\{y_1\}}U_y$ are disjoint nonempty open subsets of $X$ whose union is $X$, so $X$ is disconnected. This contradicts connectedness of $X$. Therefore $f$ is constant.
\end{proof}

