\begin{definition}
\label{def:2.9}
 Let \((X, d)\) be a metric space, and let \( E \) be a subset of \( X \). We say that \( E \) is path-connected iff, for every \( x, y \in E \), there exists a continuous function \( \gamma : [0, 1] \to E \) from the unit interval \([0, 1]\) to \( E \) such that \( \gamma(0) = x \) and \( \gamma(1) = y \). 
\end{definition}

\begin{proposition}
\label{prop:2.20}
Show that every non-empty path-connected set is connected. 
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:2.20}
Choose a point $x_0 \in \bigcap_{\alpha\in I} E_{\alpha}$. Suppose for contradiction that $E$ is not connected. Then there exist nonempty disjoint open subsets $U,V$ of $E$ (with the subspace topology) such that $E = U \cup V$.

Since $x_0 \in E$, either $x_0 \in U$ or $x_0 \in V$. By symmetry, assume $x_0 \in U$. Fix $\alpha \in I$. The set $E_{\alpha}$ is connected and satisfies
\[
\label{eq:2.u88}
E_{\alpha} = (E_{\alpha} \cap U) \cup (E_{\alpha} \cap V),
\]
where $E_{\alpha} \cap U$ and $E_{\alpha} \cap V$ are disjoint and open in the subspace topology on $E_{\alpha}$ (as intersections with open sets of $E$). Moreover, $E_{\alpha} \cap U$ is nonempty because $x_0 \in E_{\alpha} \cap U$. By connectedness of $E_{\alpha}$, it follows that $E_{\alpha} \cap V = \varnothing$, hence $E_{\alpha} \subseteq U$.

Since $\alpha \in I$ was arbitrary, $E = \bigcup_{\alpha\in I} E_{\alpha} \subseteq U$, which implies $V=\varnothing$, contradicting the choice of $V$ as nonempty. Therefore $E$ is connected.
\end{proof}

content:
\begin{theorem}
\label{thm:2.13}
Let $(X,d)$ be a metric space and let $E\subseteq X$ be nonempty. If $E$ is path-connected, then the closure $\bar{E}$ of  $E$ is connected.
\end{theorem}

proof:
\begin{proof}
\label{prf:thm:2.13}
Assume that $E$ is path-connected and suppose, for contradiction, that $E$ is not connected. Then there exist nonempty disjoint sets $A,B\subseteq E$ such that $E=A\cup B$ and $A$ and $B$ are open in the subspace topology on $E$.

Fix $a\in A$ and $b\in B$. By path-connectedness, there exists a continuous map $\gamma:[0,1]\to E$ such that $\gamma(0)=a$ and $\gamma(1)=b$. Set
\[
\label{eq:2.u89}
U:=\gamma^{-1}(A),\qquad V:=\gamma^{-1}(B).
\]
Since $A$ and $B$ are open in $E$ and $\gamma$ is continuous, $U$ and $V$ are open in $[0,1]$. Moreover, $U$ and $V$ are disjoint and
\[
\label{eq:2.u90}
[0,1]=\gamma^{-1}(E)=\gamma^{-1}(A\cup B)=U\cup V.
\]
Also $0\in U$ and $1\in V$, so $U$ and $V$ are nonempty. Thus $[0,1]$ is the union of two disjoint nonempty open sets, contradicting the connectedness of $[0,1]$.

Therefore such a separation of $E$ does not exist, and $E$ is connected.
\end{proof}

