\begin{proposition}
\label{prop:2.22}
Let $(X,d)$ be a metric space. Define a relation $\sim$ on $X$ by declaring $x\sim y$ if and only if there exists a connected subset $C\subseteq X$ such that $x\in C$ and $y\in C$. Then $\sim$ is an equivalence relation on $X$. Moreover, for each $x\in X$, the equivalence class
\[
\label{eq:2.u94}
[x]=\{y\in X: y\sim x\}
\]
is connected and closed in $X$.
\end{proposition}

\begin{definition}
\label{def:2.12}
[Topological space]
A \emph{topological space} is a pair $(X,\mathcal{F})$ consisting of a set $X$ and a collection $\mathcal{F}\subseteq 2^X$ such that:
\begin{enumerate}
\item $\emptyset\in\mathcal{F}$ and $X\in\mathcal{F}$.
\item For every $n\in\mathbb{N}$ and all $V_1,\dots,V_n\in\mathcal{F}$, the intersection $\bigcap_{i=1}^n V_i$ belongs to $\mathcal{F}$.
\item For every index set $I$ and every family $(V_\alpha)_{\alpha\in I}$ with $V_\alpha\in\mathcal{F}$ for all $\alpha\in I$, the union $\bigcup_{\alpha\in I} V_\alpha$ belongs to $\mathcal{F}$.
\end{enumerate}
The elements of $\mathcal{F}$ are called \emph{open sets}, and $\mathcal{F}$ is called a \emph{topology} on $X$.
\end{definition}

\begin{definition}
\label{def:2.13}
[Neighborhood]
Let $(X,\mathcal{F})$ be a topological space and let $x\in X$. A set $U\subseteq X$ is called a \emph{neighborhood} of $x$ if $U\in\mathcal{F}$ and $x\in U$.
\end{definition}

\begin{proposition}
\label{prop:2.23}
Let $(X,d)$ be a metric space, let $x\in X$, and let $r>0$. Then the open ball
$ B(x,r)= \{ y\in X: d(x,y)<r \}$
is a neighborhood of $x$.
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:2.23}
Since $r>0$, one has $d(x,x)=0<r$, hence $x\in B(x,r)$. Moreover, by definition of an open ball, $B(x,r)$ is an open subset of $X$. Therefore $B(x,r)$ is an open set containing $x$, so it is a neighborhood of $x$.
\end{proof}

