\begin{definition}
\label{def:2.14}
[Topological convergence]
Let $(X,\mathcal{F})$ be a topological space, let $m\in\mathbb{Z}$, and let $(x^{(n)})_{n=m}^{\infty}$ be a sequence in $X$. For $x\in X$, the sequence $(x^{(n)})_{n=m}^{\infty}$ \emph{converges to} $x$ if and only if for every neighborhood $V\subseteq X$ of $x$ there exists an integer $N\ge m$ such that $x^{(n)}\in V$ for all integers $n\ge N$.
\end{definition}

\begin{definition}
\label{def:2.15}
[Interior point, exterior point, boundary point]
Let $(X,\mathcal F)$ be a topological space, let $E\subseteq X$, and let $x_0\in X$.
\begin{enumerate}
\item The point $x_0$ is an \emph{interior point} of $E$ if there exists a neighborhood $V$ of $x_0$ such that $V\subseteq E$.
\item The point $x_0$ is an \emph{exterior point} of $E$ if there exists a neighborhood $V$ of $x_0$ such that $V\cap E=\emptyset$.
\item The point $x_0$ is a \emph{boundary point} of $E$ if $x_0$ is neither an interior point of $E$ nor an exterior point of $E$; equivalently, for every neighborhood $V$ of $x_0$, both $V\cap E\neq\emptyset$ and $V\cap (X\setminus E)\neq\emptyset$.
\end{enumerate}
\end{definition}

\begin{definition}
\label{def:2.16}
(Closure point) Let $(X,\mathcal{F})$ be a topological space and let $E\subseteq X$.
\begin{enumerate}
\item A point $x_0\in X$ is an \emph{adherent point} of $E$ if for every neighborhood $V$ of $x_0$ (that is, every set $V\subseteq X$ containing an open set that contains $x_0$), one has
\[
\label{eq:2.u99}
V\cap E\neq\varnothing.
\]
\item The \emph{closure} of $E$, denoted $\overline{E}$, is the set of all adherent points of $E$:
\[
\label{eq:2.u100}
\overline{E}=\{x\in X:\text{for every neighborhood }V\text{ of }x,\; V\cap E\neq\varnothing\}.
\]
\end{enumerate}
\end{definition}

\begin{definition}
\label{def:2.17}
Let $(X,\mathcal{F})$ be a topological space and let $K\subseteq X$. The set $K$ is \emph{closed} if and only if its complement $X\setminus K$ is open, i.e. if $X\setminus K\in\mathcal{F}$.
\end{definition}

\begin{definition}
\label{def:2.18}
[Relative topology]
Let $(X,\mathcal F)$ be a topological space and let $Y\subseteq X$. Define
\[
\label{eq:2.u101}
\mathcal F_Y := \{V\cap Y : V\in \mathcal F\}.
\]
The collection $\mathcal F_Y$ is called the \emph{relative topology} (or \emph{subspace topology}) on $Y$ induced by $(X,\mathcal F)$. The pair $(Y,\mathcal F_Y)$ is called a \emph{topological subspace} of $(X,\mathcal F)$.
\end{definition}

\begin{definition}
\label{def:2.19}
(Continuous functions) Let $(X,\mathcal{F}_X)$ and $(Y,\mathcal{F}_Y)$ be topological spaces, and let $f\colon X\to Y$ be a function. For $x_0\in X$, the function $f$ is \emph{continuous at $x_0$} if and only if for every neighborhood $V\in\mathcal{F}_Y$ of $f(x_0)$ there exists a neighborhood $U\in\mathcal{F}_X$ of $x_0$ such that $f(U)\subseteq V$. The function $f$ is \emph{continuous} if and only if it is continuous at every point $x\in X$.
\end{definition}

\begin{definition}
\label{def:2.20}
Let $(X,\mathcal{F})$ be a topological space.
\begin{enumerate}
\item The space $(X,\mathcal{F})$ is \emph{compact} if for every open cover of $X$ has a finite subcover, i.e. $(U_i)_{i\in I}\subseteq \mathcal{F}$ satisfying $X\subseteq \bigcup_{i\in I} U_i$, there exists a finite subset $J\subseteq I$ such that $X\subseteq \bigcup_{i\in J} U_i$.
\item A subset $Y\subseteq X$ is \emph{compact} if the topological space $\bigl(Y,\{U\cap Y: U\in \mathcal{F}\}\bigr)$ is compact.
\end{enumerate}
\end{definition}

\begin{definition}
Let $X$ be a set and define $\mathcal{F}:=\{\emptyset,X\}$. Show that the pair $(X,\mathcal{F})$ is a topology on $X$.
\end{definition}

\begin{definition}
\label{def:2.22}
[Hausdorff topological space]\label{def:hausdorff}
A topological space $(X,\mathcal{F})$ is \emph{Hausdorff} if for any distinct points $x,y\in X$ there exist neighborhoods $V$ of $x$ and $W$ of $y$ such that $V\cap W=\emptyset$.
\end{definition}

\begin{definition}
\label{def:2.23}
[Order topology]\label{def:order-topology}
Let $(X,\leq)$ be a totally ordered set. A set $V\subseteq X$ is \emph{open} if for every $x\in V$ there exists a set $I$ containing $x$ and contained in $V$, where $I$ is one of the following:
\begin{itemize}
\item an interval $\{y\in X: a<y<b\}$ for some $a,b\in X$,
\item a ray $\{y\in X: a<y\}$ for some $a\in X$,
\item a ray $\{y\in X: y<b\}$ for some $b\in X$,
\item the whole space $X$.
\end{itemize}
Let $\mathcal{F}$ be the collection of all such open sets. Then $(X,\mathcal{F})$ is called the \emph{order topology} on $(X,\leq)$.
\end{definition}

\begin{proposition}
\label{prop:2.24}
Let $(x_n)_{n=1}^\infty$ be a sequence in $\mathbb{R}$, viewed as a sequence in the extended real line $\overline{\mathbb{R}}=\mathbb{R}\cup\{-\infty,+\infty\}$. Then $x_n\to +\infty$ if and only if
\[
\label{eq:2.u102}
\liminf_{n\to\infty} x_n = +\infty.
\]
Similarly, $x_n\to -\infty$ if and only if
\[
\label{eq:2.u103}
\limsup_{n\to\infty} x_n = -\infty.
\]
\end{proposition}

\begin{definition}
\label{def:2.24}
[Cofinite topology]\label{def:cofinite-topology}
Let $X$ be a set. Define $\mathcal{F}:=\{E\subseteq X: E=\emptyset\ \text{or}\ X\setminus E\ \text{is finite}\}$. The pair $(X,\mathcal{F})$ is called the \emph{cofinite topology} on $X$.
\end{definition}

\begin{definition}
\label{def:2.25}
[Cocountable topology]\label{def:cocountable-topology}
Let $X$ be a set. Define $\mathcal{F}:=\{E\subseteq X: E=\emptyset\ \text{or}\ X\setminus E\ \text{is at most countable}\}$. The pair $(X,\mathcal{F})$ is called the \emph{cocountable topology} on $X$.
\end{definition}

\begin{definition}
\label{def:2.26}
[First countable topological space]\label{def:first-countable}
A topological space $(X,\mathcal{F})$ is \emph{first countable} if for every $x\in X$ there exists a countable collection of neighborhoods $V_1,V_2,\ldots$ of $x$ such that every neighborhood of $x$ contains at least one $V_n$.
\end{definition}
